window.EXAM_CHAPTER_DATA["west_econ"]["12_AD-AS模型"] = {"id":"12_AD-AS模型","name":"AD-AS模型","kps":[{"id":"KP01","name":"AD总需求曲线","file":"教材笔记/06_西方经济学/12_AD-AS模型/知识点/KP01_AD总需求曲线.md","questions":[{"id":"west_econ_12_AD-AS模型_KP01_1","num":"1","stem":"总需求曲线向右下方倾斜的原因不包括以下哪一项？","options":{"A":"利率效应","B":"财富效应","C":"汇率效应","D":"规模报酬递减效应"},"answer":"D"},{"id":"west_econ_12_AD-AS模型_KP01_2","num":"2","stem":"利率效应是指物价水平上升导致：","options":{"A":"利率上升，投资减少","B":"利率下降，投资增加","C":"利率上升，投资增加","D":"利率下降，投资减少"},"answer":"A"},{"id":"west_econ_12_AD-AS模型_KP01_3","num":"3","stem":"财富效应（庇古效应）发生的机制是：","options":{"A":"物价上升使居民持有货币的实际购买力下降，消费减少","B":"物价上升使股票市值上升，消费增加","C":"物价上升使利率上升，投资减少","D":"物价上升使出口减少，净出口下降"},"answer":"A"},{"id":"west_econ_12_AD-AS模型_KP01_4","num":"4","stem":"下列哪种情况会使AD曲线向右移动？","options":{"A":"政府购买减少","B":"央行提高法定准备金率","C":"企业对未来利润预期乐观","D":"本国物价水平上升"},"answer":"C"},{"id":"west_econ_12_AD-AS模型_KP01_5","num":"5","stem":"沿AD曲线移动与AD曲线整体移动的区别在于：","options":{"A":"沿AD移动由物价变化引起，AD整体移动由财政货币政策引起","B":"沿AD移动由财政政策引起，AD整体移动由物价变化引起","C":"两者没有区别","D":"沿AD移动由技术进步引起，AD整体移动由工资变化引起"},"answer":"A"},{"id":"west_econ_12_AD-AS模型_KP01_6","num":"6","stem":"已知IS曲线为 $Y = 1200 - 300r$，货币需求 $L = 0.5Y - 100r$，名义货币供给 $M = 500$。当 $P = 1$ 时，由IS-LM决定的均衡产出 $Y$ 为：","options":{"A":"800","B":"900","C":"1000","D":"1200"},"answer":"B"},{"id":"west_econ_12_AD-AS模型_KP01_7","num":"7","stem":"AD曲线描述的是：","options":{"A":"一种商品价格与需求量的关系","B":"总体物价水平与均衡总产出的关系","C":"利率与投资的关系","D":"汇率与净出口的关系"},"answer":"B"},{"id":"west_econ_12_AD-AS模型_KP01_8","num":"8","stem":"下列哪一项不会使AD曲线移动？","options":{"A":"政府增加基础设施投资","B":"央行在公开市场买入债券","C":"本国物价水平普遍上涨","D":"外国经济繁荣导致出口增加"},"answer":"C"},{"id":"west_econ_12_AD-AS模型_KP01_9","num":"9","stem":"关于AD曲线，下列说法错误的是：","options":{"A":"扩张性财政政策使AD右移","B":"扩张性货币政策使AD右移","C":"AD曲线是微观需求曲线的简单加总","D":"AD曲线向右下方倾斜"},"answer":"C"}]},{"id":"KP02","name":"短期总供给曲线","file":"教材笔记/06_西方经济学/12_AD-AS模型/知识点/KP02_短期总供给曲线.md","questions":[{"id":"west_econ_12_AD-AS模型_KP02_1","num":"1","stem":"短期总供给曲线的一般形式是：","options":{"A":"$Y = Y_f$","B":"$Y = Y_f + \\alpha(P - P^e)$","C":"$Y = C + I + G + NX$","D":"$MV = PY$"},"answer":"B"},{"id":"west_econ_12_AD-AS模型_KP02_2","num":"2","stem":"短期总供给曲线向右上方倾斜的原因不包括：","options":{"A":"名义工资刚性","B":"企业对相对价格的错觉","C":"价格粘性（菜单成本）","D":"货币供给内生"},"answer":"D"},{"id":"west_econ_12_AD-AS模型_KP02_3","num":"3","stem":"工资刚性理论认为，物价上升时企业增产是因为：","options":{"A":"名义工资不变，实际工资下降，劳动成本降低","B":"名义工资上升，实际工资不变","C":"企业产品相对价格上升","D":"菜单成本下降"},"answer":"A"},{"id":"west_econ_12_AD-AS模型_KP02_4","num":"4","stem":"错觉理论（卢卡斯）认为企业增产是因为：","options":{"A":"企业误以为自己产品相对价格上升，实际是整体物价上升","B":"名义工资下降","C":"菜单成本下降","D":"政府增加补贴"},"answer":"A"},{"id":"west_econ_12_AD-AS模型_KP02_5","num":"5","stem":"粘性价格理论的\"菜单成本\"是指：","options":{"A":"企业印制菜单的成本","B":"企业调整价格的成本（重新印刷价目表、通知客户等）","C":"餐饮业的人工成本","D":"物价上升导致的生活成本"},"answer":"B"},{"id":"west_econ_12_AD-AS模型_KP02_6","num":"6","stem":"已知 $Y_f = 2000$，$\\alpha = 200$，$P^e = 100$。当 $P = 105$ 时，短期产出 $Y$ 为：","options":{"A":"2000","B":"2100","C":"1900","D":"2200"},"answer":"B"},{"id":"west_econ_12_AD-AS模型_KP02_7","num":"7","stem":"凯恩斯极端情形下，短期总供给曲线的形状是：","options":{"A":"垂直","B":"向右上方倾斜","C":"水平","D":"向右下方倾斜"},"answer":"C"},{"id":"west_econ_12_AD-AS模型_KP02_8","num":"8","stem":"下列哪种情况会使短期总供给曲线向左移动？","options":{"A":"名义工资上升","B":"技术进步","C":"资本存量增加","D":"预期物价下降"},"answer":"A"},{"id":"west_econ_12_AD-AS模型_KP02_9","num":"9","stem":"关于短期总供给曲线，下列说法正确的是：","options":{"A":"短期AS与长期AS形状相同","B":"短期AS的位置由预期物价 $P^e$ 决定","C":"物价变化使SRAS整体移动","D":"短期AS垂直于潜在产出"},"answer":"B"}]},{"id":"KP03","name":"长期总供给曲线","file":"教材笔记/06_西方经济学/12_AD-AS模型/知识点/KP03_长期总供给曲线.md","questions":[{"id":"west_econ_12_AD-AS模型_KP03_1","num":"1","stem":"长期总供给曲线的形状是：","options":{"A":"向右上方倾斜","B":"向右下方倾斜","C":"垂直于潜在产出 $Y_f$","D":"水平"},"answer":"C"},{"id":"west_econ_12_AD-AS模型_KP03_2","num":"2","stem":"长期总供给曲线垂直的原因是：","options":{"A":"工资和价格在长期中充分灵活调整","B":"企业有货币幻觉","C":"菜单成本为零","D":"政府价格管制"},"answer":"A"},{"id":"west_econ_12_AD-AS模型_KP03_3","num":"3","stem":"货币中性是指：","options":{"A":"货币供给变化只影响名义变量，不影响实际变量","B":"货币供给变化对经济没有任何影响","C":"货币供给变化只影响实际变量","D":"货币需求不稳定"},"answer":"A"},{"id":"west_econ_12_AD-AS模型_KP03_4","num":"4","stem":"下列哪种情况会使长期总供给曲线向右移动？","options":{"A":"央行增加货币供给","B":"技术进步","C":"政府增加购买","D":"物价水平上升"},"answer":"B"},{"id":"west_econ_12_AD-AS模型_KP03_5","num":"5","stem":"长期中扩张性货币政策的效应是：","options":{"A":"产出增加，物价上升","B":"产出不变，物价上升","C":"产出增加，物价不变","D":"产出和物价都不变"},"answer":"B"},{"id":"west_econ_12_AD-AS模型_KP03_6","num":"6","stem":"当短期均衡产出 $Y > Y_f$ 时，长期调整过程是：","options":{"A":"工人预期物价上升，要求涨工资，SRAS左移，产出回到 $Y_f$","B":"工人预期物价下降，SRAS右移","C":"AD自动左移","D":"LRAS右移"},"answer":"A"},{"id":"west_econ_12_AD-AS模型_KP03_7","num":"7","stem":"潜在产出 $Y_f$ 的决定因素不包括：","options":{"A":"劳动力数量","B":"资本存量","C":"技术水平","D":"货币供给量"},"answer":"D"},{"id":"west_econ_12_AD-AS模型_KP03_8","num":"8","stem":"关于长期总供给曲线，下列说法错误的是：","options":{"A":"LRAS垂直于 $Y_f$","B":"LRAS的位置由资本、劳动、技术决定","C":"扩张性财政政策使LRAS右移","D":"长期经济增长表现为LRAS不断右移"},"answer":"C"},{"id":"west_econ_12_AD-AS模型_KP03_9","num":"9","stem":"古典学派与凯恩斯学派在AS问题上的根本分歧是：","options":{"A":"古典认为AS垂直，凯恩斯认为AS水平或右上倾斜","B":"古典认为AS水平，凯恩斯认为AS垂直","C":"两者都认为AS垂直","D":"两者都认为AS水平"},"answer":"A"}]},{"id":"KP04","name":"AD-AS均衡与冲击","file":"教材笔记/06_西方经济学/12_AD-AS模型/知识点/KP04_ADAS均衡与冲击.md","questions":[{"id":"west_econ_12_AD-AS模型_KP04_1","num":"1","stem":"长期均衡的条件是：","options":{"A":"AD与SRAS相交","B":"AD与LRAS相交","C":"AD、SRAS、LRAS三线交于同一点","D":"SRAS与LRAS相交"},"answer":"C"},{"id":"west_econ_12_AD-AS模型_KP04_2","num":"2","stem":"扩张性财政政策使AD右移，短期效应是：","options":{"A":"产出增加，物价上升","B":"产出增加，物价下降","C":"产出不变，物价上升","D":"产出下降，物价上升"},"answer":"A"},{"id":"west_econ_12_AD-AS模型_KP04_3","num":"3","stem":"不利供给冲击（如石油涨价）使：","options":{"A":"AD左移","B":"SRAS左移","C":"LRAS右移","D":"AD右移"},"answer":"B"},{"id":"west_econ_12_AD-AS模型_KP04_4","num":"4","stem":"滞胀是指：","options":{"A":"产出上升与物价上升同时发生","B":"产出下降与物价上升同时发生","C":"产出上升与物价下降同时发生","D":"产出下降与物价下降同时发生"},"answer":"B"},{"id":"west_econ_12_AD-AS模型_KP04_5","num":"5","stem":"面对滞胀，扩张性需求管理政策的效应是：","options":{"A":"产出回到潜在水平，物价进一步上升","B":"产出回到潜在水平，物价下降","C":"产出不变，物价下降","D":"产出下降，物价上升"},"answer":"A"},{"id":"west_econ_12_AD-AS模型_KP04_6","num":"6","stem":"1970年代石油危机后，菲利普斯曲线：","options":{"A":"向左下方移动","B":"向右上方移动","C":"保持不变","D":"变为水平线"},"answer":"B"},{"id":"west_econ_12_AD-AS模型_KP04_7","num":"7","stem":"已知 $Y_f = 1000$，AD：$Y = 2000 - 10P$，SRAS：$Y = 1000 + 100(P - 100)$。短期均衡物价 $P$ 为：","options":{"A":"90","B":"100","C":"110","D":"120"},"answer":"B"},{"id":"west_econ_12_AD-AS模型_KP04_8","num":"8","stem":"技术进步（有利供给冲击）的效应是：","options":{"A":"SRAS左移，物价上升，产出下降","B":"SRAS右移，物价下降，产出上升","C":"AD右移，物价上升，产出上升","D":"LRAS不动"},"answer":"B"},{"id":"west_econ_12_AD-AS模型_KP04_9","num":"9","stem":"2020年新冠疫情对经济的冲击属于：","options":{"A":"单一需求冲击","B":"单一供给冲击","C":"需求与供给双重冲击","D":"货币政策冲击"},"answer":"C"},{"id":"west_econ_12_AD-AS模型_KP04_10","num":"10","stem":"关于需求冲击与供给冲击，下列说法错误的是：","options":{"A":"需求冲击下产出与物价同方向变动","B":"供给冲击下产出与物价反方向变动","C":"需求冲击可以用需求管理政策有效应对","D":"供给冲击下需求管理政策可以同时解决通胀和失业"},"answer":"D"}]},{"id":"KP99","name":"曲线移动专项","file":"","questions":[{"id":"west_econ_12_AD-AS模型_KP99_1","num":"1","stem":"（曲线移动·判断题）政府大规模发行专项债投资新基建，在 AD-AS 模型中短期会使哪条曲线怎么移？（　）","options":{"A":"AD 曲线右移，P 上升、Y 上升","B":"SAS 曲线左移，P 上升、Y 下降","C":"LAS 曲线右移，P 下降、Y 上升","D":"AD 曲线左移，P 下降、Y 下降"},"answer":"A"},{"id":"west_econ_12_AD-AS模型_KP99_2","num":"2","stem":"（曲线移动·判断题）国际油价暴涨 3 倍（不利供给冲击），短期 AD-AS 中哪条曲线怎么移？（　）","options":{"A":"AD 右移","B":"SAS 曲线上移（左移），P 上升、Y 下降","C":"LAS 右移","D":"SAS 下移，P 下降、Y 上升"},"answer":"B"},{"id":"west_econ_12_AD-AS模型_KP99_3","num":"3","stem":"（曲线移动·判断题）社会普遍预期明年物价会大涨（预期通胀 $P^e$ 上升），短期 SAS 如何移动？（　）","options":{"A":"SAS 下移，P 下降","B":"SAS 上移，P 上升、Y 下降","C":"AD 右移","D":"LAS 左移"},"answer":"B"},{"id":"west_econ_12_AD-AS模型_KP99_4","num":"4","stem":"（曲线移动·判断）一项重大技术突破（如 AI 革命）大幅提高潜在产出，长期看哪条曲线怎么移？（　）","options":{"A":"AD 右移","B":"LAS 曲线右移，长期产出 Y* 上升、物价 P 下降","C":"SAS 上移","D":"LAS 不动"},"answer":"B"},{"id":"west_econ_12_AD-AS模型_KP99_5","num":"5","stem":"（曲线移动·绘图分析）经济原本在长期均衡，现在 AD 突然右移（如政府大肆发钱）。短期与长期物价产出各怎么走？（　）","options":{"A":"短期 P↑Y↑，长期预期调整使 SAS 上移，Y 回到 Y*、P 更高","B":"一直停在 Y>Y*","C":"SAS 立刻下移","D":"LAS 右移"},"answer":"A"}]}]};
